<?php
require __DIR__.'/app/bootstrap.php';
$userId=require_auth();$pdo=db();$service=new TravelMatchService($pdo);$users=new UserService($pdo);$upload=new UploadService(__DIR__);$profile=$service->extendedProfile($userId);$account=$users->account($userId);$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        $existingPhotos=$profile['photos']??[];
        $beforeAvatar=(string)($account['avatar_url']??'');
        $primaryFile=$_FILES['photo_1']??null;
        if($primaryFile && (int)($primaryFile['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){
            $newUrl=$upload->storeImage($primaryFile,$userId,'avatars');
            if($newUrl){$users->updateAvatar($userId,$newUrl);if($beforeAvatar!==''&&$beforeAvatar!==$newUrl)$upload->deleteLocal($beforeAvatar);$account=$users->account($userId);}
        }
        $_POST['photo_1']=(string)($account['avatar_url']??'');
        for($i=2;$i<=4;$i++){
            $existing=$existingPhotos[$i-1]['photo_url']??'';
            if(!empty($_POST['remove_photo_'.$i])){if($existing)$upload->deleteLocal($existing);$_POST['photo_'.$i]='';continue;}
            $file=$_FILES['photo_'.$i]??null;
            if($file && (int)($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$newUrl=$upload->storeImage($file,$userId,'matching');if($newUrl){if($existing)$upload->deleteLocal($existing);$_POST['photo_'.$i]=$newUrl;continue;}}
            $_POST['photo_'.$i]=$existing;
        }
        $profile=$service->saveProfile($userId,$_POST);
        flash('success',!empty($profile['enabled'])?'You are enrolled in Travel Matching and discoverable to compatible profiles.':'You are unenrolled from Travel Matching. Existing matches and messages are preserved, but your profile is no longer discoverable.');
        if(!empty($_SESSION['pending_match_invite'])){$token=(string)$_SESSION['pending_match_invite'];unset($_SESSION['pending_match_invite']);redirect('match-invite.php?token='.urlencode($token));}
        if(!empty($_SESSION['pending_match_game'])){$token=(string)$_SESSION['pending_match_game'];unset($_SESSION['pending_match_game']);redirect('match-game.php?token='.urlencode($token));}
        redirect('matching.php');
    }catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'We could not save your Travel Match profile.';$profile=$service->extendedProfile($userId);$account=$users->account($userId);}
}
$p=$profile?:[];$d=$p['dealbreakers']??[];$photos=$p['photos']??[];$prompts=$p['prompts']??[];$primaryPhoto=(string)($account['avatar_url']??($photos[0]['photo_url']??($p['photo_url']??'')));$promptCatalog=$service->promptCatalog();$readiness=$profile?$service->profileReadiness($userId,true):['score'=>0,'ready'=>false,'missing'=>[]];
$title='Travel Match Profile';require __DIR__.'/partials/header.php';
?>
