<article class="dashboard-card"><h2>Home base</h2><div class="field"><label>City</label><input name="home_city" maxlength="120" value="<?=e($p['home_city']??'')?>" placeholder="Phoenix"></div><div class="field"><label>State / region</label><input name="home_region" maxlength="120" value="<?=e($p['home_region']??'')?>" placeholder="Arizona"></div><div class="field"><label>Country</label><input name="home_country" maxlength="120" value="<?=e($p['home_country']??'')?>" placeholder="United States"></div><div class="field"><label>Favorite destination</label><input name="favorite_destination" maxlength="180" value="<?=e($p['favorite_destination']??'')?>" placeholder="Cabo, Maui, Rome..."></div></article>
<article class="dashboard-card"><h2>Travel style</h2><div class="field"><label>Pace</label><select name="travel_pace"><option value="slow" <?=($p['travel_pace']??'balanced')==='slow'?'selected':''?>>Slow — one real thing per day</option><option value="balanced" <?=($p['travel_pace']??'balanced')==='balanced'?'selected':''?>>Balanced</option><option value="packed" <?=($p['travel_pace']??'balanced')==='packed'?'selected':''?>>Packed — we came here to do things</option></select></div><div class="field"><label>Budget style</label><select name="budget_style"><option value="budget" <?=($p['budget_style']??'comfortable')==='budget'?'selected':''?>>Budget-conscious</option><option value="comfortable" <?=($p['budget_style']??'comfortable')==='comfortable'?'selected':''?>>Comfortable</option><option value="premium" <?=($p['budget_style']??'comfortable')==='premium'?'selected':''?>>Premium when it matters</option></select></div></article>
</div>
<article class="dashboard-card"><div class="section-head compact-head"><div><span class="eyebrow">Photos</span><h2>Your account photo leads the gallery.</h2><p>Your main Account Settings profile picture is always Photo 1. Add up to three extra Travel Match-only photos; people can click forward/back through them in discovery.</p></div></div><div class="matching-upload-grid"><?php for($i=1;$i<=4;$i++):$existing=$i===1?$primaryPhoto:($photos[$i-1]['photo_url']??'');?><div class="matching-upload-slot"><?php if($existing):?><img src="<?=e($existing)?>" alt="Travel Match photo <?=$i?>"><?php else:?><div class="matching-upload-placeholder"><span><?= $i===1?'Primary':'Photo '.$i ?></span></div><?php endif;?><div class="field"><label><?= $i===1?'Account / primary photo':'Photo '.$i ?></label><input name="photo_<?=$i?>" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted"><?= $i===1?'Changing this also changes your Account Settings profile picture.':'Travel Match-only · JPEG, PNG, or WebP · 8 MB max.' ?></small></div><?php if($i>1&&$existing):?><label class="check-row compact"><input type="checkbox" name="remove_photo_<?=$i?>" value="1"> Remove this photo</label><?php endif;?></div><?php endfor;?></div></article>
